#include "stdio.h"
#include <version_autogenerated.h>
#include "gxhwlib_registers.h"
#include "time.h"
#include "otp.h"

#if defined CONFIG_ARCH_CKMMU_GX6605S
#define CHIP_NAME_START        (0x150)
#define CHIP_NAME_END          (0x15B)
#define PUBLIC_ID_START        (0x148)
#define PUBLIC_ID_END          (0x14F)
#define SCPU_CON_START         (0xFFF)
#define SCPU_CON_END           (0xFFF)
#endif
#if defined CONFIG_ARCH_CKMMU_GX3211
#define CHIP_NAME_START        (0x354)
#define CHIP_NAME_END          (0x35f)
#define PUBLIC_ID_START        (0x348)
#define PUBLIC_ID_END          (0x34F)
#define SCPU_CON_START         (0x364)
#define SCPU_CON_END           (0x367)
#endif

#ifndef CONFIG_ARCH_CKMMU_TAURUS
#define GX3211_CHIP_PUBLIC_ID1    (0xA030a560)
#define GX3211_CHIP_PUBLIC_ID2    (0xA030a564)
#define GX3211_CHIP_NAME_REG1     (0xA030a190)
#define GX3211_CHIP_NAME_REG2     (0xA030a194)
#define GX3211_CHIP_NAME_REG3     (0xA030a198)
#define GX3211_SCPU_CON_REG       (0xA030a574)
#endif

#define BETWEEN(value, min, max)  ((unsigned int)value < (unsigned int)min ? 0 : \
		        ((unsigned int)value > (unsigned int)max ? 0 : 1))

extern void sec_write(unsigned int addr, unsigned int value, unsigned int delay);
extern unsigned int sec_read(unsigned int addr, unsigned int delay);

static int gx3211_otp_read_regiter_one_byte(unsigned int start_addr, unsigned char *data)
{
#if defined CONFIG_ARCH_CKMMU_TAURUS || defined CONFIG_ARCH_CKMMU_GEMINI || defined CONFIG_ARCH_CKMMU_CYGNUS || defined CONFIG_ARCH_CKMMU_SCORPIO \
	|| defined CONFIG_ARCH_CKMMU_SCORPIO_TAURUS
	return 0;
#else
	unsigned int fir = 0;
	unsigned int sec = 0;
	unsigned int number = 0;
	unsigned int *reg = NULL;
	unsigned int otp_start = 0;

	if (BETWEEN(start_addr, PUBLIC_ID_START, PUBLIC_ID_END)) {
		reg = (unsigned int *)GX3211_CHIP_PUBLIC_ID1;
		otp_start = PUBLIC_ID_START;
	} else if (BETWEEN(start_addr, CHIP_NAME_START, CHIP_NAME_END)) {
		reg = (unsigned int *)GX3211_CHIP_NAME_REG1;
		otp_start = CHIP_NAME_START;
	} else if (BETWEEN(start_addr, SCPU_CON_END, SCPU_CON_END)) { //only 0x367 be mapped to 0xA030a574[31:24]
		reg = (unsigned int *)GX3211_SCPU_CON_REG;
		otp_start = SCPU_CON_START;
	} else
		return 0;

	number = start_addr - otp_start;
	fir = number / 4;
	sec = number % 4;
	*data = ((*(reg + fir)) >> (sec * 8)) & 0xff;

	return 1;
#endif
}

int gx_otp_read(unsigned int start_addr, int rd_num, unsigned char *data)
{
	int i;
	unsigned int _data;
	unsigned int otp_con_reg;

#if defined(CONFIG_ARCH_CKMMU_GX6605S)
	_data = sec_read(GX_OTP_CFG_REG, 65535);
	sec_write(GX_OTP_CFG_REG, _data | 0x00000001,65535);
#endif
	otp_con_reg = 0x00000000; // set all control signals to be invalid, address to 0x1800(default)
	while (1) // check if OTP Controller is ready
	{
		_data = sec_read(GX_OTP_STA_REG, 65535);
		if ((_data & (1 << 10)) != 0)
			break;
	}
	for (i = 0; i < rd_num; i++) {
        if (gx3211_otp_read_regiter_one_byte(0x7ff & (start_addr + i), &data[i]))
            continue;
		otp_con_reg = (0x7ff & (start_addr+i))<<3;  // start address
		while (1) // check if OTP Controller is busy now; 1 for busy
		{
			_data = sec_read(GX_OTP_STA_REG, 65535);
			if ((_data & 0x100) == 0)
				break;
		}
		sec_write(GX_OTP_CON_REG,otp_con_reg | (0x1 << 14),65535); // set READEN
		gx_time_delay_us(64);
		_data = sec_read(GX_OTP_CON_REG, 65535);
		sec_write(GX_OTP_CON_REG, _data & (~(0x1 << 14)), 65535); // clear READEN
		while (1) // chekc if OTP data is ready
		{
			_data = sec_read(GX_OTP_STA_REG, 65535);
			if ((_data & 0x200) != 0)
				break;
		}
		_data = sec_read(GX_OTP_STA_REG, 65535);
		data[i] = (unsigned char)(_data & 0xFF);
		sec_write(GX_OTP_CON_REG, 0x0, 65535);
	}
	sec_write(GX_OTP_CON_REG, 0x0, 65535); // set all control signals to be invalid, address to 0x1800(default)
	return rd_num;
}

#ifdef CONFIG_ENABLE_OTP_FULLFUNCTION
#ifdef CONFIG_ARCH_CKMMU_GX6605S
/*gx6650s multiplex configure*/
#define GX6605S_REG_PINMUX_PORTA  (0x0030a13c + GX_REG_VIRTUAL_BASE1)
#define GX6605S_REG_PINMUX_PORTB  (0x0030a140 + GX_REG_VIRTUAL_BASE1)
#define PORTA_20                  (20)
#define PORTB_11                  (11)
static char porta_20 = 0;
static char portb_11 = 0;
#endif

static void otp_multipin_switch(void)
{
#ifdef CONFIG_ARCH_CKMMU_GX6605S
	porta_20 = REG_GET_BIT(GX6605S_REG_PINMUX_PORTA, PORTA_20);
	portb_11 = REG_GET_BIT(GX6605S_REG_PINMUX_PORTB, PORTB_11);
	/* switch to otp */
	REG_SET_CLR_BIT(GX6605S_REG_PINMUX_PORTA, PORTA_20, 0);
	REG_SET_CLR_BIT(GX6605S_REG_PINMUX_PORTB, PORTB_11, 1);
#endif
}

static void otp_multipin_recover(void)
{
#ifdef CONFIG_ARCH_CKMMU_GX6605S
	REG_SET_CLR_BIT(GX6605S_REG_PINMUX_PORTA, PORTA_20, porta_20);
	REG_SET_CLR_BIT(GX6605S_REG_PINMUX_PORTB, PORTB_11, portb_11);
#endif
}

int gx_otp_write(unsigned int start_addr, int wr_num, unsigned char *data)
{
	int i;
	unsigned int _data;
	unsigned int otp_con_reg;

#if defined(CONFIG_ARCH_CKMMU_GX6605S)
	_data = sec_read(GX_OTP_CFG_REG, 65535);
	sec_write(GX_OTP_CFG_REG, _data | 0x00000001,65535);
#endif
	otp_con_reg = 0x00000000; // set all control signals to be invalid, address to 0x1800(default)
	otp_multipin_switch();
	while (1) // check if OTP Controller is ready
	{
		_data = sec_read(GX_OTP_STA_REG, 65535);
		if ((_data & (1 << 10)) != 0)
			break;
	}

	for (i = 0; i < wr_num; i++) {
		otp_con_reg = (0x7ff & (start_addr+i))<<3; // start address
		otp_con_reg &= ~(0xff<<16);
		otp_con_reg |= data[i] << 16;
		while (1) // check if OTP Controller is busy now; 1 for busy
		{
			_data = sec_read(GX_OTP_STA_REG, 65535);
			if ((_data & 0x100) == 0)
				break;
		}
		sec_write(GX_OTP_CON_REG,otp_con_reg | (0x1 << 15),65535); // set BURN
		gx_time_delay_us(64);
		sec_write(GX_OTP_CON_REG, otp_con_reg, 65535); // clear BURN
		gx_time_delay_us(64);
	}
	otp_multipin_recover();
	sec_write(GX_OTP_CON_REG, 0x0, 65535); // set all control signals to be invalid, address to 0x1800(default)
	return wr_num;
}
#endif

bool gx_otp_query_flag(int flag)
{
#ifdef IS_TAURUS_SERIES
	switch(flag) {
	case OTP_FLAG_DDR_CONTENT_LIMIT:
		if (OTP_FLAG_IS_TRUE(BIT_OTP_FLAG_DDR_CONTENT_LIMIT))
			return true;
		break;

	case OTP_FLAG_DDR_SCRAMBLE:
		if (OTP_FLAG_IS_TRUE(BIT_OTP_FLAG_DDR_SCRAMBLE))
			return true;
		break;

	case OTP_FLAG_TS_BUF_PROTECT:
		if (OTP_FLAG_IS_TRUE(BIT_OTP_FLAG_TS_BUF_PROTECT))
			return true;
		break;

	case OTP_FLAG_ES_BUF_PROTECT:
		if (OTP_FLAG_IS_TRUE(BIT_OTP_FLAG_ES_BUF_PROTECT))
			return true;
		break;

	case OTP_FLAG_FW_BUF_PROTECT:
		if (OTP_FLAG_IS_TRUE(BIT_OTP_FLAG_FW_BUF_PROTECT))
			return true;
		break;

	case OTP_FLAG_SCPU_BUF_PROTECT:
		if (OTP_FLAG_IS_TRUE(BIT_OTP_FLAG_SCPU_BUF_PROTECT))
			return true;
		break;

	default:
		break;
	}
#endif
	return false;
}
